#!/usr/bin/env bash
# Patch 100 voor hrmforce-site: zes site-aanpassingen (26-10-2026).
#
#   bash toepassen-100.sh
#
# - /kenniscentrum/gemiddeld-iq/: nieuwe title en meta description; tabel met
#   IQ per regio vervangen door een alinea over omstreden landenvergelijkingen
#   (alle zes talen); Lynn & Vanhanen uit de bronnen; "Bronnen:" in plaats van
#   de zin over het Deep Research Report
# - /oefentest/: introtekst in de navy hero lichtgrijs (#dbe6f5)
# - /voorbereiding/: tekst "Voorbereiden op een assessment" boven de camera- en
#   geluidstest
# - Henry-chatbubbel op telefoon kleiner (44px) en verborgen op /demo/,
#   /oefentest/, /oefenen/, /gratis-kleurentest/ en de camera- en geluidstest
# - /demo/: "Drie velden en één keuze, dat is alles."
