Gemiddeld IQ, oefentest-intro, voorbereiding, chatbubbel en demo-zin

Gemiddeld IQ krijgt een nieuwe title en meta description; de tabel met IQ per
regio maakt in alle talen plaats voor een alinea over de omstreden
landenvergelijkingen. De introtekst op /oefentest/ is leesbaar op navy, de
voorbereidingstekst staat boven de camera- en geluidstest, de chatbubbel is op
telefoon kleiner en verdwijnt op de demo- en testpagina's.

